// Python-3 str repr reimplementation (Unicode 15.0 assumed via V8 tables)
function isPrintable(cp){
  if(cp===0x20) return true;
  if(cp>=0xD800&&cp<=0xDFFF) return false;
  const s=String.fromCodePoint(cp);
  return !/^[\p{Cc}\p{Cf}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]$/u.test(s);
}
function pyrepr(str){
  const cps=Array.from(str);
  const hasS=cps.includes("'"), hasD=cps.includes('"');
  const q = (hasS && !hasD) ? '"' : "'";
  let out=q;
  for(const ch of cps){
    const cp=ch.codePointAt(0);
    if(ch===q||ch==='\\') out+='\\'+ch;
    else if(ch==='\t') out+='\\t';
    else if(ch==='\n') out+='\\n';
    else if(ch==='\r') out+='\\r';
    else if(isPrintable(cp)) out+=ch;
    else if(cp<0x100) out+='\\x'+cp.toString(16).padStart(2,'0');
    else if(cp<0x10000) out+='\\u'+cp.toString(16).padStart(4,'0');
    else out+='\\U'+cp.toString(16).padStart(8,'0');
  }
  return out+q;
}
module.exports={pyrepr};
if(require.main===module){
  const cp=parseInt(process.argv[2],10);
  process.stdout.write(pyrepr('x'+String.fromCodePoint(cp)+'_'));
}
